/**
 * @name Command injection via subprocess
 * @description User-controlled data flowing to subprocess execution can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-distlib
 * @tags security
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    exists(DataFlow::Node argv |
      argv = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource() and
      source = argv
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in archive extraction
 * @description Extracting archive entries without validating paths can allow writing outside intended directory
 * @kind path-problem
 * @problem.severity error
 * @id py/zipslip-distlib
 * @tags security
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      // ZipFile.namelist() or TarFile.getnames() or member.name
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("namelist").getACall() or
      call = API::moduleImport("tarfile").getMember("TarFile").getReturn().getMember("getnames").getACall() or
      call = API::moduleImport("tarfile").getMember("TarFile").getReturn().getMember("getmembers").getACall() or
      // Getting name from archive member
      exists(DataFlow::AttrRead attr |
        attr.getAttributeName() = "name" or
        attr.getAttributeName() = "filename" |
        source = attr
      )
      |
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // File operations that write to paths
      call = API::moduleImport("os").getMember("path").getMember("join").getACall() or
      call = API::builtin("open").getACall() or
      call = API::moduleImport("shutil").getMember(["copy", "copy2", "copyfile", "move"]).getACall() or
      // Extract operations
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember(["extract", "extractall"]).getACall() or
      call = API::moduleImport("tarfile").getMember("TarFile").getReturn().getMember(["extract", "extractall"]).getACall()
      |
      sink = call.getArg(_)
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from archive entry $@.", source.getNode(), "name"

/**
 * @name Code injection in script generation
 * @description User-controlled data flowing into generated scripts can lead to code injection
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-script-distlib
 * @tags security
 * @cwe cwe-94
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters that could be user-controlled
    exists(DataFlow::ParameterNode param |
      param.getParameter().getName() in ["name", "script", "data", "content", "entry_point"] and
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Writing to files or executing code
    exists(DataFlow::CallCfgNode call |
      (
        call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["write", "writelines"] or
        call = API::builtin("exec").getACall() or
        call = API::builtin("eval").getACall() or
        call = API::builtin("compile").getACall()
      ) and
      sink = call.getArg(_)
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code injection from $@.", source.getNode(), "user input"
